import{_ as o,o as e,c as a,a5 as p}from"./chunks/framework.DJo0M80U.js";const g=JSON.parse('{"title":"Apache POI","description":"","frontmatter":{"title":"Apache POI","date":"2026-07-03T00:00:00.000Z","categories":["Java 快速入门"],"tags":["Java","常见需求","OneNote"],"lastUpdated":false},"headers":[],"relativePath":"posts/java快速入门/第十部分：常见需求/Office转pdf/Apache POI.md","filePath":"posts/java快速入门/第十部分：常见需求/Office转pdf/Apache POI.md"}'),r={name:"posts/java快速入门/第十部分：常见需求/Office转pdf/Apache POI.md"};function i(l,t,c,s,n,d){return e(),a("div",null,[...t[0]||(t[0]=[p('<div><p>Apache POI 是一个用于读取和写入 Microsoft Office 文件格式的 Java 库。以下是使用 Apache POI 进行操作的详细步骤：</p><ol><li>添加依赖 考虑到您需要处理的所有文件格式，我们需要确保 Apache POI 的所有相关库都被包含。另外，要处理 PDF，您可能需要另一个库，如 Apache PDFBox。让我们来调整您的 Maven 依赖。</li></ol><p>以下是一个更完整的依赖列表： &lt;!-- Apache POI 核心库，支持 .xls 和 .doc --&gt; &lt;dependency&gt; &lt;groupId&gt;org.apache.poi&lt;/groupId&gt; &lt;artifactId&gt;poi&lt;/artifactId&gt; &lt;version&gt;5.1.0&lt;/version&gt; &lt;/dependency&gt;</p><p>&lt;!-- 支持 .xlsx, .docx, .pptx 等 OOXML 文件 --&gt; &lt;dependency&gt; &lt;groupId&gt;org.apache.poi&lt;/groupId&gt; &lt;artifactId&gt;poi-ooxml&lt;/artifactId&gt; &lt;version&gt;5.1.0&lt;/version&gt; &lt;/dependency&gt;</p><p>&lt;!-- 支持 .doc 和 .ppt --&gt; &lt;dependency&gt; &lt;groupId&gt;org.apache.poi&lt;/groupId&gt; &lt;artifactId&gt;poi-scratchpad&lt;/artifactId&gt; &lt;version&gt;5.1.0&lt;/version&gt; &lt;/dependency&gt;</p><p>&lt;!-- Apache PDFBox 用于处理 PDF 文件 --&gt; &lt;dependency&gt; &lt;groupId&gt;org.apache.pdfbox&lt;/groupId&gt; &lt;artifactId&gt;pdfbox&lt;/artifactId&gt; &lt;version&gt;2.0.24&lt;/version&gt; &lt;!-- 注意检查此版本，可能会有更新 --&gt; &lt;/dependency&gt; 现在，您应该已经具备了处理所有提到的文件格式的能力。如果在处理时遇到特定的 OOXML 功能需求或问题，您还可以考虑添加 poi-ooxml-full，但目前看来，上述的依赖应该足够满足大多数常见需求。</p><p>此外，根据你需要处理的文件类型，你可能还需要考虑以下依赖：</p><p>对于 .doc：poi-scratchpad 对于 .ppt：poi-scratchpad 对于图像处理和一些特殊的功能：poi-ooxml-full 但基于你目前的需求，我认为上面的两个依赖应该足够了。如果在开发过程中遇到问题，你可以根据需要添加更多的依赖。</p><ol start="2"><li>读取和写入 Excel 文件 读取 Excel 文件：</li></ol><p>java Copy code import org.apache.poi.ss.usermodel.*; import org.apache.poi.xssf.usermodel.XSSFWorkbook;</p><p>import java.io.File; import java.io.FileInputStream; import java.io.IOException;</p><p>public class ExcelReader { public static void main(String[] args) throws IOException { FileInputStream fis = new FileInputStream(new File(&quot;path_to_your_file.xlsx&quot;)); Workbook workbook = new XSSFWorkbook(fis); Sheet firstSheet = workbook.getSheetAt(0); for (Row row : firstSheet) { for (Cell cell : row) { String cellValue = new DataFormatter().formatCellValue(cell); System.out.print(cellValue + &quot;\\t&quot;); } System.out.println(); } workbook.close(); fis.close(); } } 写入 Excel 文件：</p><p>java Copy code import org.apache.poi.ss.usermodel.*; import org.apache.poi.xssf.usermodel.XSSFWorkbook;</p><p>import java.io.File; import java.io.FileOutputStream; import java.io.IOException;</p><p>public class ExcelWriter { public static void main(String[] args) throws IOException { Workbook workbook = new XSSFWorkbook(); Sheet sheet = workbook.createSheet(&quot;FirstSheet&quot;); Row row = sheet.createRow(0); Cell cell = row.createCell(0); cell.setCellValue(&quot;Hello, World!&quot;);</p><p>FileOutputStream fos = new FileOutputStream(new File(&quot;output.xlsx&quot;)); workbook.write(fos); fos.close(); workbook.close(); } } 3. 读取和写入 Word 文件 读取 Word 文件：</p><p>java Copy code import org.apache.poi.xwpf.usermodel.XWPFDocument; import org.apache.poi.xwpf.usermodel.XWPFParagraph;</p><p>import java.io.File; import java.io.FileInputStream; import java.io.IOException; import java.util.List;</p><p>public class WordReader { public static void main(String[] args) throws IOException { FileInputStream fis = new FileInputStream(new File(&quot;path_to_your_file.docx&quot;)); XWPFDocument document = new XWPFDocument(fis); List&lt;XWPFParagraph&gt; paragraphs = document.getParagraphs(); for (XWPFParagraph paragraph : paragraphs) { System.out.println(paragraph.getText()); } document.close(); fis.close(); } } 写入 Word 文件：</p><p>java Copy code import org.apache.poi.xwpf.usermodel.XWPFDocument; import org.apache.poi.xwpf.usermodel.XWPFParagraph;</p><p>import java.io.File; import java.io.FileOutputStream; import java.io.IOException;</p><p>public class WordWriter { public static void main(String[] args) throws IOException { XWPFDocument document = new XWPFDocument(); XWPFParagraph paragraph = document.createParagraph(); paragraph.createRun().setText(&quot;Hello, World!&quot;);</p><p>FileOutputStream fos = new FileOutputStream(new File(&quot;output.docx&quot;)); document.write(fos); fos.close(); document.close(); } } 请注意，Apache POI 支持多种 Office 文件格式，上面的示例仅展示了 .xlsx 和 .docx 格式的基本操作。对于其他格式，例如 .xls 和 .doc，你需要稍微调整代码。此外，Apache POI 还提供了众多的高级功能，如样式、公式、图片等。如果需要，你可以查阅Apache POI 的官方文档以获取更多信息。</p></div>',1)])])}const m=o(r,[["render",i]]);export{g as __pageData,m as default};
